#include <bits/stdc++.h>
using namespace std;

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    int m = 3 * n;
	    vector<long long> a(m);
	    for(auto &x : a)
	        cin>>x;
	        
	    sort(a.begin(), a.end(), greater<long long>());
	    vector<long long > pref(m + 1, 0);
	    for(int i = 0; i < m; i++)
	    pref[i + 1] = pref[i] + a[i];
	    
	    long long ans = 0;
	    for(int  A = 0; A <= n ; A++){
	        int low = 0;
	        int high = n - A;
	        while(low < high){
	            int B = (low + high) / 2;
	            int K = 3 * n - 2 * A - B;
	            int M = A + 2 * B;
	            long long delta = a[M] + a[M + 1] - 3LL * a[K - 1];
	            if(delta >= 0)
	            low = B + 1;
	            else
	            high = B;
	        }
	        for(int B : {max(0, low - 1), low}){
	            if(B < 0 || B > n - A)
	            continue;
	            int K = 3 * n - 2 * A - B;
	            int M = A + 2 * B;
	            long long  value = 3LL * pref[K] + 2LL * pref[A] + pref[M];
	            ans  = max(ans, value);
	        }
	    }
	    cout<<ans << "\n";
	}
	return 0;

}
